-- Local demo data, loaded by `supabase db reset`. Every account signs in with the password kurious-demo-2027.

insert into auth.users (
  instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
  raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
  confirmation_token, recovery_token, email_change_token_new, email_change,
  email_change_token_current, phone_change, phone_change_token, reauthentication_token
)
select
  '00000000-0000-0000-0000-000000000000',
  u.id,
  'authenticated',
  'authenticated',
  u.email,
  extensions.crypt('kurious-demo-2027', extensions.gen_salt('bf')),
  now() - interval '30 days',
  '{"provider": "email", "providers": ["email"]}',
  jsonb_build_object('name', u.name, 'locale', 'es'),
  now() - interval '30 days',
  now() - interval '30 days',
  '', '', '', '', '', '', '', ''
from (values
  ('a0000000-0000-4000-8000-000000000001'::uuid, 'marc@kurious.local', 'Marc'),
  ('a0000000-0000-4000-8000-000000000002'::uuid, 'laura@kurious.local', 'Laura'),
  ('a0000000-0000-4000-8000-000000000003'::uuid, 'alex@kurious.local', 'Álex'),
  ('a0000000-0000-4000-8000-000000000004'::uuid, 'julia@kurious.local', 'Júlia'),
  ('a0000000-0000-4000-8000-000000000005'::uuid, 'santiago@kurious.local', 'Santiago')
) as u (id, email, name);

insert into auth.identities (
  provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at
)
select
  u.id::text,
  u.id,
  jsonb_build_object('sub', u.id::text, 'email', u.email, 'email_verified', true, 'phone_verified', false),
  'email',
  u.created_at,
  u.created_at,
  u.created_at
from auth.users u
where u.email like '%@kurious.local';

